SRC = 'static/index.html'
STEPS = [
 ('  function scan(){var out=[];VIEWS3.forEach(function(v){var r=document.getElementById("view-"+v);if(!r)return;Array.prototype.forEach.call(r.querySelectorAll(".card"),function(c){var h=c.querySelector("h2");if(!h)return;var t=h.textContent.trim();if(!t||c.classList.contains("sxfind"))return;out.push({v:v,c:c,t:t,tl:t.toLowerCase(),x:(c.textContent||"").toLowerCase()})})});return out}\n  function find(q){var w=words(q);if(!w.length)return[];var seen={},res=[];\n   scan().forEach(function(k){var s=0;w.forEach(function(x){if(k.tl.indexOf(x.w)>=0)s+=x.o?6:4;else if(k.x.indexOf(x.w)>=0)s+=x.o?2:1});if(s>0){seen[k.tl]=1;res.push({s:s,v:k.v,c:k.c,t:k.t})}});\n   FB.forEach(function(f){if(seen[f[0].toLowerCase()])return;var s=0;w.forEach(function(x){if(f[2].indexOf(x.w)>=0)s+=x.o?4:2});if(s>0)res.push({s:s,v:f[1],c:null,t:f[0]})});\n   res.sort(function(a,b){return b.s-a.s});return res.slice(0,5)}\n  function go(r){var h="#"+r.v;if(location.hash!==h)location.hash=h;else window.dispatchEvent(new Event("hashchange"));\n   setTimeout(function(){var c=r.c;if(!c||!document.body.contains(c)){var f=scan().filter(function(k){return k.t===r.t&&k.v===r.v})[0];c=f&&f.c}if(!c)return;c.scrollIntoView({behavior:"smooth",block:"center"});c.classList.add("sxflash");setTimeout(function(){c.classList.remove("sxflash")},2600)},260)}\n',
  '  /*SF4-start: search lists single settings and lands on the exact one*/\n  function labels(c){var o=[],seen={};Array.prototype.forEach.call(c.querySelectorAll(".field label,.switch b"),function(l){var t=l.textContent.trim().replace(/\\s*\\([^()]*0 = off\\)\\s*$/,"");if(t.length<3||t.length>90||seen[t])return;seen[t]=1;o.push(t)});return o}\n  function scan(){var out=[];VIEWS3.forEach(function(v){var r=document.getElementById("view-"+v);if(!r)return;Array.prototype.forEach.call(r.querySelectorAll(".card"),function(c){var h=c.querySelector("h2")||c.querySelector(".shgo b");if(!h)return;var t=h.textContent.trim();if(!t||c.classList.contains("sxfind"))return;out.push({v:v,c:c,t:t,tl:t.toLowerCase(),x:(c.textContent||"").toLowerCase(),fl:labels(c)})})});return out}\n  function find(q){var w=words(q);if(!w.length)return[];var seen={},res=[];\n   scan().forEach(function(k){var s=0,ts=0;w.forEach(function(x){if(k.tl.indexOf(x.w)>=0){s+=x.o?6:4;ts+=1}else if(k.x.indexOf(x.w)>=0)s+=x.o?2:1});seen[k.tl]=1;var fh=[];\n    k.fl.forEach(function(f){var fl=f.toLowerCase(),fs=0;w.forEach(function(x){if(fl.indexOf(x.w)>=0)fs+=x.o?8:5});if(fs>0)fh.push({s:fs+s/2,v:k.v,c:k.c,t:k.t,f:f})});\n    fh.sort(function(a,b){return b.s-a.s});fh.slice(0,2).forEach(function(r){res.push(r)});\n    if(s>0&&(!fh.length||ts>0))res.push({s:s,v:k.v,c:k.c,t:k.t})});\n   FB.forEach(function(f){if(seen[f[0].toLowerCase()])return;var s=0;w.forEach(function(x){if(f[2].indexOf(x.w)>=0)s+=x.o?4:2});if(s>0)res.push({s:s,v:f[1],c:null,t:f[0]})});\n   res.sort(function(a,b){return b.s-a.s});return res.slice(0,6)}\n  var st2=document.createElement("style");st2.textContent=".field.sxflash,.switch.sxflash{border-radius:14px;background:var(--green-soft,rgba(47,184,100,.15))}";document.head.appendChild(st2);\n  function fieldEl(c,ft){if(!c||!ft)return null;var want=ft.toLowerCase(),hit=null;Array.prototype.forEach.call(c.querySelectorAll(".field,.switch"),function(e){if(hit)return;var l=e.matches(".switch")?e.querySelector("b"):e.querySelector("label");if(!l)return;var t=l.textContent.trim().toLowerCase();if(t&&(t===want||t.indexOf(want)>=0||want.indexOf(t)>=0))hit=e});return hit}\n  function go(r){var h="#"+r.v;if(location.hash!==h)location.hash=h;else window.dispatchEvent(new Event("hashchange"));\n   var tries=0;function look(){tries++;var c=r.c;if(!c||!document.body.contains(c)){var f=scan().filter(function(k){return k.t===r.t&&k.v===r.v})[0];c=f&&f.c}\n    if(!c){if(r.t&&tries<10)setTimeout(look,250);return}\n    var e=r.f?fieldEl(c,r.f):null;if(r.f&&!e&&tries<8){setTimeout(look,250);return}\n    var folded=c.classList.contains("fold");if(folded){var hh=c.querySelector(".card-head h2");if(hh)hh.click()}\n    setTimeout(function(){var tg=e&&document.body.contains(e)?e:(fieldEl(c,r.f)||c);tg.scrollIntoView({behavior:"smooth",block:"center"});tg.classList.add("sxflash");setTimeout(function(){tg.classList.remove("sxflash")},tg===c?2600:3400)},folded?480:0)}\n   setTimeout(look,260)}\n  /*SF4-end*/\n'),
 ('b.firstChild.textContent=r.t+"  ·  "+({bot:"Bot tab",profile:"Profile",connect:"Connect",trades:"Trades",home:"Home"}[r.v]||r.v);', 'b.firstChild.textContent=(r.f?r.f+"  ·  ":"")+r.t+"  ·  "+({bot:"Bot tab",profile:"Profile",connect:"Connect",trades:"Trades",home:"Home"}[r.v]||r.v);'),
 ('check:"run check"};', 'check:"run check",share:"share friend code",friend:"share code",code:"share friend",close:"profit close",early:"profit close small",entry:"entries stake",limits:"limit loss"};'),
 ('window.SXgo({ v: D.fix.view, t: D.fix.card || "", c: null });', 'window.SXgo({ v: D.fix.view, t: D.fix.card || "", c: null, f: D.fix.label || "" });'),
]
s = open(SRC, encoding='utf-8').read(); n = 0
for old, new in STEPS:
    if new in s: continue
    if s.count(old) != 1: sys.exit('STOP: cannot find exactly once: ' + old[:70].replace('\n', ' '))
    s = s.replace(old, new); n += 1
if n: open(SRC, 'w', encoding='utf-8', newline='').write(s); print('static/index.html : %d step(s) done' % n)
else: print('already ok, nothing to do')
